import { test, expect } from '@playwright/test';

test.describe('Dropdown Menu - Escape Key Closure', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dropdown');
  });

  test('should close dropdown when Escape key is pressed', async ({ page }) => {
    // Open dropdown by clicking the button
    const dropdownButton = page.getByRole('button', { name: /open dropdown/i });
    await dropdownButton.click();

    // Verify dropdown is visible
    const dropdownMenu = page.getByRole('menuitem', { name: /options/i });
    await expect(dropdownMenu).toBeVisible();

    // Press Escape key
    await page.keyboard.press('Escape');

    // Verify dropdown is closed
    await expect(dropdownMenu).not.toBeVisible();

    // Verify button text is reset
    await expect(dropdownButton).toHaveText('Open dropdown');
  });

  test('should handle Escape key press when dropdown is not open', async ({ page }) => {
    // Verify dropdown is initially closed
    const dropdownButton = page.getByRole('button', { name: /open dropdown/i });
    await expect(dropdownButton).toHaveText('Open dropdown');

    // Press Escape key when dropdown is closed
    await page.keyboard.press('Escape');

    // Verify dropdown remains closed
    const dropdownMenu = page.getByRole('menuitem', { name: /options/i });
    await expect(dropdownMenu).not.toBeVisible();

    // Verify button text is unchanged
    await expect(dropdownButton).toHaveText('Open dropdown');
  });
});
